// ---- internal PRNG (replaces libc rand/lrand48; same algorithm as lrand48/srand48) ----
	.text
	.p2align	2
	.hidden	bd_rand
	.type	bd_rand,@function
bd_rand:
	adrp	x8, bd_rng
	ldr	x9, [x8, :lo12:bd_rng]
	mov	x10, #0xE66D
	movk	x10, #0xDEEC, lsl #16
	movk	x10, #0x5, lsl #32
	mov	x11, #11
	madd	x9, x9, x10, x11
	ubfx	x9, x9, #0, #48
	str	x9, [x8, :lo12:bd_rng]
	lsr	x0, x9, #17
	ret
	.size	bd_rand, .-bd_rand

	.p2align	2
	.hidden	bd_srand
	.type	bd_srand,@function
bd_srand:
	adrp	x8, bd_rng
	lsl	x9, x0, #16
	mov	x10, #0x330E
	orr	x9, x9, x10
	str	x9, [x8, :lo12:bd_rng]
	ret
	.size	bd_srand, .-bd_srand

	.section	.bss.bd_rng,"aw",@nobits
	.p2align	3
	.type	bd_rng,@object
bd_rng:
	.xword	0
	.size	bd_rng, 8
